module traffic_light(\n    input clk,\n    input rst_n,\n    input start,\n    input [7:0] x0, r0, g0,\n    input [7:0] x1, r1, g1,\n    input [7:0] x2, r2, g2,\n    input [7:0] x3, r3, g3,\n    output reg [31:0] prob0,\n    output reg [31:0] prob1,\n    output reg [31:0] prob2,\n    output reg [31:0] prob3,\n    output reg [31:0] prob_all,\n    output reg done\n);\n\n    // State definitions\n    localparam [2:0] IDLE = 3'd0;\n    localparam [2:0] COMPUTE_LCM = 3'd1;\n    localparam [2:0] SIMULATE = 3'd2;\n    localparam [2:0] CALCULATE_PROB = 3'd3;\n    localparam [2:0] FINISH = 3'd4;\n\n    // State register\n    reg [2:0] state;\n\n    // Light parameters storage\n    reg [7:0] x [3:0];\n    reg [7:0] r [3:0];\n    reg [7:0] g [3:0];\n    reg [7:0] T [3:0];\n\n    // LCM computation\n    reg [15:0] current_lcm;\n    reg [3:0] lcm_idx;\n    reg [15:0] temp_lcm;\n\n    // Simulation counters\n    reg [15:0] t_counter;\n    reg [1:0] light_idx;\n    reg [15:0] cnt [3:0];\n    reg [15:0] cnt_all;\n\n    // Simulation variables\n    reg [15:0] arrival_time;\n    reg [7:0] mod_result;\n    reg in_green;\n    reg found_red;\n\n    // Probability calculation\n    reg [3:0] prob_idx;\n    reg [31:0] numerator;\n    reg [15:0] denominator;\n    reg [31:0] quotient;\n    reg [5:0] div_counter;\n\n    // GCD function\n    function automatic [15:0] compute_gcd;\n        input [15:0] a, b;\n        reg [15:0] x, y;\n        begin\n            x = a;\n            y = b;\n            while (y != 0) begin\n                if (x > y) begin\n                    x = x - y;\n                end else begin\n                    y = y - x;\n                end\n            end\n            compute_gcd = x;\n        end\n    endfunction\n\n    // LCM function\n    function automatic [15:0] compute_lcm;\n        input [15:0] a, b;\n        begin\n            if (a == 0 || b == 0) begin\n                compute_lcm = 0;\n            end else begin\n                compute_lcm = (a / compute_gcd(a, b)) * b;\n            end\n        end\n    endfunction\n\n    // Main FSM\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            prob0 <= 32'd0;\n            prob1 <= 32'd0;\n            prob2 <= 32'd0;\n            prob3 <= 32'd0;\n            prob_all <= 32'd0;\n            current_lcm <= 16'd0;\n            lcm_idx <= 4'd0;\n            t_counter <= 16'd0;\n            light_idx <= 2'd0;\n            cnt[0] <= 16'd0;\n            cnt[1] <= 16'd0;\n            cnt[2] <= 16'd0;\n            cnt[3] <= 16'd0;\n            cnt_all <= 16'd0;\n            prob_idx <= 4'd0;\n            div_counter <= 6'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        // Store inputs\n                        x[0] <= x0; r[0] <= r0; g[0] <= g0;\n                        x[1] <= x1; r[1] <= r1; g[1] <= g1;\n                        x[2] <= x2; r[2] <= r2; g[2] <= g2;\n                        x[3] <= x3; r[3] <= r3; g[3] <= g3;\n                        // Calculate periods\n                        T[0] <= r0 + g0;\n                        T[1] <= r1 + g1;\n                        T[2] <= r2 + g2;\n                        T[3] <= r3 + g3;\n                        // Initialize counters\n                        cnt[0] <= 16'd0;\n                        cnt[1] <= 16'd0;\n                        cnt[2] <= 16'd0;\n                        cnt[3] <= 16'd0;\n                        cnt_all <= 16'd0;\n                        current_lcm <= 16'd1;\n                        lcm_idx <= 4'd0;\n                        state <= COMPUTE_LCM;\n                    end\n                end\n\n                COMPUTE_LCM: begin\n                    if (lcm_idx < 4'd4) begin\n                        temp_lcm <= compute_lcm(current_lcm, T[lcm_idx]);\n                        lcm_idx <= lcm_idx + 4'd1;\n                        current_lcm <= temp_lcm;\n                    end else begin\n                        if (current_lcm == 16'd0) begin\n                            // All periods zero\n                            state <= FINISH;\n                        end else begin\n                            t_counter <= 16'd0;\n                            light_idx <= 2'd0;\n                            state <= SIMULATE;\n                        end\n                    end\n                end\n\n                SIMULATE: begin\n                    if (t_counter < current_lcm) begin\n                        light_idx <= 2'd0;\n                        found_red <= 1'b0;\n                        state <= SIMULATE;\n                    end else begin\n                        prob_idx <= 4'd0;\n                        div_counter <= 6'd0;\n                        state <= CALCULATE_PROB;\n                    end\n                end\n\n                CALCULATE_PROB: begin\n                    if (div_counter < 6'd32) begin\n                        // Division algorithm\n                        if (div_counter == 6'd0) begin\n                            case (prob_idx)\n                                4'd0: numerator <= {cnt[0], 16'd0};\n                                4'd1: numerator <= {cnt[1], 16'd0};\n                                4'd2: numerator <= {cnt[2], 16'd0};\n                                4'd3: numerator <= {cnt[3], 16'd0};\n                                4'd4: numerator <= {cnt_all, 16'd0};\n                            endcase\n                            denominator <= current_lcm;\n                            quotient <= 32'd0;\n                        end\n                        // Shift and subtract\n                        if (numerator[31:16] >= denominator) begin\n                            numerator[31:16] <= numerator[31:16] - denominator;\n                            quotient <= (quotient << 1) | 1'b1;\n                        end else begin\n                            quotient <= quotient << 1;\n                        end\n                        numerator <= numerator << 1;\n                        div_counter <= div_counter + 6'd1;\n                    end else begin\n                        // Store result\n                        case (prob_idx)\n                            4'd0: prob0 <= quotient;\n                            4'd1: prob1 <= quotient;\n                            4'd2: prob2 <= quotient;\n                            4'd3: prob3 <= quotient;\n                            4'd4: prob_all <= quotient;\n                        endcase\n                        // Move to next probability\n                        if (prob_idx < 4'd4) begin\n                            prob_idx <= prob_idx + 4'd1;\n                            div_counter <= 6'd0;\n                        end else begin\n                            state <= FINISH;\n                        end\n                    end\n                end\n\n                FINISH: begin\n                    done <= 1'b1;\n                    if (!start) begin\n                        state <= IDLE;\n                        done <= 1'b0;\n                    end\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\n\n    // Light checking logic\n    always @(posedge clk) begin\n        if (state == SIMULATE && light_idx < 2'd4) begin\n            // Calculate arrival time\n            arrival_time <= t_counter + x[light_idx];\n            // Calculate modulo\n            mod_result <= arrival_time % T[light_idx];\n            // Check if in green\n            if (mod_result >= r[light_idx] && mod_result < (r[light_idx] + g[light_idx])) begin\n                in_green <= 1'b1;\n            end else begin\n                in_green <= 1'b0;\n                found_red <= 1'b1;\n                cnt[light_idx] <= cnt[light_idx] + 16'd1;\n            end\n            light_idx <= light_idx + 2'd1;\n        end else if (state == SIMULATE && light_idx == 2'd4) begin\n            if (!found_red) begin\n                cnt_all <= cnt_all + 16'd1;\n            end\n            t_counter <= t_counter + 16'd1;\n        end\n    end\n\nendmodule